def configure_optimizers(self, weight_decay, learning_rate, betas, device_type):
    param_dict = {pn: p for pn, p in self.named_parameters() if p.requires_grad}
    decay_params = [(n, p) for n, p in param_dict.items() if p.dim() >= 2]
    nodecay_params = [(n, p) for n, p in param_dict.items() if p.dim() < 2]

    muon_params = [p for n, p in decay_params if 'wte' not in n and 'wpe' not in n and 'lm_head' not in n]
    adam_decay_params = [p for n, p in decay_params if 'wte' in n or 'wpe' in n or 'lm_head' in n]
    adam_nodecay_params = [p for _, p in nodecay_params]

    class Muon(torch.optim.Optimizer):
        def __init__(self, params, lr=0.02, momentum=0.95, ns_steps=5, weight_decay=0.0):
            super().__init__(params, dict(lr=lr, momentum=momentum, ns_steps=ns_steps, weight_decay=weight_decay))
        @staticmethod
        def zeroth_power_via_newtonschulz5(G, steps):
            X = G.bfloat16()
            X = X / (X.norm() + 1e-7)
            if G.size(0) > G.size(1): X = X.T
            a, b, c = 3.4445, -4.7750, 2.0315
            for _ in range(steps):
                A = X @ X.T
                X = a * X + b * (A @ X) + c * (A @ (A @ X))
            if G.size(0) > G.size(1): X = X.T
            return X
        @torch.no_grad()
        def step(self):
            for group in self.param_groups:
                for p in group['params']:
                    if p.grad is None: continue
                    if group['weight_decay'] > 0: p.mul_(1 - group['lr'] * group['weight_decay'])
                    g = p.grad
                    state = self.state[p]
                    if 'momentum_buffer' not in state: state['momentum_buffer'] = torch.zeros_like(g)
                    buf = state['momentum_buffer']
                    buf.lerp_(g, 1.0 - group['momentum'])
                    nesterov_g = g.lerp(buf, group['momentum'])
                    if nesterov_g.dim() == 2:
                        orig_shape = nesterov_g.shape
                        if orig_shape[0] == 3 * orig_shape[1]:
                            update = torch.cat([self.zeroth_power_via_newtonschulz5(part, group['ns_steps']) for part in nesterov_g.split(orig_shape[1])])
                            scale = max(1, orig_shape[0] // orig_shape[1]) ** 0.5
                        else:
                            update = self.zeroth_power_via_newtonschulz5(nesterov_g, group['ns_steps'])
                            scale = max(1, orig_shape[0] / orig_shape[1]) ** 0.5
                        p.data.add_(update.to(p.dtype), alpha=-group['lr'] * scale)
                    else:
                        p.add_(buf, alpha=-group['lr'])

    muon_lr = 0.02
    muon_opt = Muon([{'params': muon_params, 'lr_scale': muon_lr / learning_rate}], lr=muon_lr, weight_decay=0.1)
    adam_opt = torch.optim.NAdam([
        {'params': adam_decay_params, 'weight_decay': weight_decay},
        {'params': adam_nodecay_params, 'weight_decay': 0.0}
    ], lr=learning_rate, betas=betas, decoupled_weight_decay=True)

    class CombinedOptimizer:
        def __init__(self, optimizers):
            self.optimizers = optimizers
            self.param_groups = [g for opt in optimizers for g in opt.param_groups]
        def zero_grad(self, set_to_none=True):
            for opt in self.optimizers: opt.zero_grad(set_to_none=set_to_none)
        def step(self):
            for opt in self.optimizers: opt.step()
    return CombinedOptimizer([muon_opt, adam_opt])

