        {'params': adam_nodecay_params, 'weight_decay': 0.0}
    ], lr=learning_rate, betas=betas, decoupled_weight_decay=True)

    class CombinedOptimizer:
        def __init__(self, optimizers):
            self.optimizers = optimizers
            self.param_groups = [g for opt in optimizers for g in opt.param_groups]
            self.step_count = 0
            self.max_iters = 12030
            self.warmup_iters = 1000
            self.decay_iters = 2400
            self.stable_iters = self.max_iters - self.decay_iters
            self.base_lr = learning_rate
            self.min_lr = 0.0
        def zero_grad(self, set_to_none=True):
            for opt in self.optimizers: opt.zero_grad(set_to_none=set_to_none)
        def step(self):
            self.step_count += 1
            it = self.step_count - 1
            if it < self.warmup_iters:
                lr = self.base_lr * (it + 1) / (self.warmup_iters + 1)
            elif it < self.stable_iters:
                lr = self.base_lr
            else:
                decay_ratio = (it - self.stable_iters) / self.decay_iters
                decay_ratio = min(1.0, max(0.0, decay_ratio))
                lr = self.min_lr + 0.5 * (self.base_lr - self.min_lr) * (1.0 + math.cos(math.pi * decay_ratio))
            for opt in self.optimizers:
